# Illustrator AI Assistant - Windows COM launcher (Windows PowerShell 5.1+).
#
# Runs ONE build script generated by this tool inside Adobe Illustrator via
# COM (Illustrator.Application.DoJavaScriptFile). It is normally started by
# tools/vf.py (--run-illustrator), after explicit human approval.
#
# Safety rules implemented here:
#   * Only a file named illustrator_build.jsx is accepted, and only when
#     (a) its SHA-256 equals -ExpectedSha256, (b) its code skeleton equals
#     this tool's template, (c) its six data lines are plain literals, and
#     (d) its three output paths are illustrator_output.ai/.svg/.png inside
#     the script's own folder. Arbitrary ExtendScript is refused.
#   * Refuses when any output file or a previous run record exists
#     (nothing is overwritten; a run is never repeated in the same folder).
#   * Refuses when Illustrator already has documents open.
#   * Never closes documents, never quits or terminates Illustrator, never
#     retries, never deletes files. On failure everything is left in place.
#   * A returned script is NOT proof of a valid .ai file. The record says
#     only what happened; opening and inspecting the .ai is a human step.
#
# Exit codes: 0 = script returned, 2 = refused (Illustrator not asked to run
# the script), 3 = Illustrator reported a script error.
# Results: refusals and -ValidateOnly print one JSON object to stdout; an
# actual run writes illustrator_run.json (-ResultPath) next to the script.
#
# Note: if this launcher starts Illustrator, Illustrator stays open afterwards.

param(
    [Parameter(Mandatory = $true)][string]$JsxPath,
    [Parameter(Mandatory = $true)][string]$ExpectedSha256,
    [Parameter(Mandatory = $true)][string]$ResultPath,
    [switch]$ValidateOnly
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# Must equal vectorfidelity.illustrator.jsx.skeleton_sha256() (checked by tests).
$SkeletonSha256 = '9109b7e0578de786840f9afb9533267877727e748b0ea82ef87774bde27eb16b'

$JsxFileName = 'illustrator_build.jsx'
$RunRecordName = 'illustrator_run.json'
$TargetNames = @('illustrator_output.ai', 'illustrator_output.svg', 'illustrator_output.png')
$DataLineIndexes = @(5, 6, 7, 8, 9, 10)
$DataLinePatterns = @(
    '^    var W = \d+, H = \d+;$',
    '^    var OUT_AI = "(?:[^"\\]|\\.)*";$',
    '^    var OUT_SVG = "(?:[^"\\]|\\.)*";$',
    '^    var OUT_PNG = "(?:[^"\\]|\\.)*";$',
    '^    var BG = \[\d+, \d+, \d+\];$',
    '^    var REGIONS = \[(?:\{"color":\[\d+,\d+,\d+\],"loops":\[(?:\[(?:\[-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?\],?)+\],?)+\]\},?)*\];$'
)

function Get-Sha256Hex([string]$Text) {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($Text)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $hash = $sha.ComputeHash($bytes)
    } finally {
        $sha.Dispose()
    }
    return (($hash | ForEach-Object { $_.ToString('x2') }) -join '')
}

function Write-StdoutJson($Object) {
    [Console]::Out.WriteLine(($Object | ConvertTo-Json -Depth 6 -Compress))
}

function Stop-Refused([string]$Reason, [string]$Detail) {
    Write-StdoutJson @{ status = 'REFUSED'; reason = $Reason; detail = $Detail }
    exit 2
}

function Get-OutputInfo([string]$Dir) {
    $list = @()
    foreach ($name in $TargetNames) {
        $path = Join-Path $Dir $name
        $exists = Test-Path -LiteralPath $path -PathType Leaf
        $size = 0
        if ($exists) { $size = (Get-Item -LiteralPath $path).Length }
        $list += @{ name = $name; exists = $exists; bytes = $size }
    }
    return $list
}

# ---------------------------------------------------------------- validation
$jsxFull = [System.IO.Path]::GetFullPath($JsxPath)
if ([System.IO.Path]::GetFileName($jsxFull) -cne $JsxFileName) {
    Stop-Refused 'BAD_SCRIPT_NAME' "only $JsxFileName is accepted"
}
if (-not (Test-Path -LiteralPath $jsxFull -PathType Leaf)) {
    Stop-Refused 'SCRIPT_NOT_FOUND' $jsxFull
}
$dir = [System.IO.Path]::GetDirectoryName($jsxFull)

$resultFull = [System.IO.Path]::GetFullPath($ResultPath)
$expectedResult = Join-Path $dir $RunRecordName
if (-not [string]::Equals($resultFull, $expectedResult, [System.StringComparison]::OrdinalIgnoreCase)) {
    Stop-Refused 'BAD_RESULT_PATH' "result must be $RunRecordName next to the script"
}
if (Test-Path -LiteralPath $resultFull) {
    Stop-Refused 'RUN_RECORD_EXISTS' 'a run was already attempted in this folder; it is never repeated automatically'
}

$raw = [System.IO.File]::ReadAllText($jsxFull, [System.Text.Encoding]::UTF8)
$text = $raw.Replace("`r`n", "`n")
$actualSha = Get-Sha256Hex $text
if ($actualSha -ne $ExpectedSha256.ToLowerInvariant()) {
    Stop-Refused 'HASH_MISMATCH' 'script content differs from what the tool generated'
}

$lines = $text.Split("`n")
if ($lines.Length -le 10) {
    Stop-Refused 'NOT_A_GENERATED_SCRIPT' 'script is too short'
}
for ($i = 0; $i -lt $DataLineIndexes.Length; $i++) {
    $idx = $DataLineIndexes[$i]
    if ($lines[$idx] -cnotmatch $DataLinePatterns[$i]) {
        Stop-Refused 'NOT_A_GENERATED_SCRIPT' "line $($idx + 1) is not an expected data literal"
    }
}
$skeletonLines = @()
for ($i = 0; $i -lt $lines.Length; $i++) {
    if ($DataLineIndexes -notcontains $i) { $skeletonLines += $lines[$i] }
}
if ((Get-Sha256Hex ($skeletonLines -join "`n")) -ne $SkeletonSha256) {
    Stop-Refused 'NOT_A_GENERATED_SCRIPT' 'script code differs from the tool template'
}

$base = $dir.Replace('\', '/').TrimEnd('/')
for ($i = 0; $i -lt $TargetNames.Length; $i++) {
    $line = $lines[$DataLineIndexes[$i + 1]]
    $literal = $line.Substring($line.IndexOf(' = ') + 3)
    $literal = $literal.Substring(0, $literal.Length - 1)
    $value = [string]($literal | ConvertFrom-Json)
    $expected = "$base/$($TargetNames[$i])"
    if (-not [string]::Equals($value, $expected, [System.StringComparison]::OrdinalIgnoreCase)) {
        Stop-Refused 'BAD_OUTPUT_PATH' "output path must be $($TargetNames[$i]) inside the script folder"
    }
    if (Test-Path -LiteralPath (Join-Path $dir $TargetNames[$i])) {
        Stop-Refused 'OUTPUT_EXISTS' "$($TargetNames[$i]) already exists; nothing is overwritten"
    }
}

if ($ValidateOnly) {
    Write-StdoutJson @{ status = 'VALIDATED'; jsx_sha256 = $actualSha; detail = 'checks passed; Illustrator was not contacted' }
    exit 0
}

# ----------------------------------------------------------------- Illustrator
$app = $null
try {
    $app = New-Object -ComObject Illustrator.Application
} catch {
    Stop-Refused 'ILLUSTRATOR_COM_UNAVAILABLE' $_.Exception.Message
}

$docsBefore = -1
try {
    $docsBefore = [int]$app.Documents.Count
} catch {
    Stop-Refused 'ILLUSTRATOR_STATE_UNKNOWN' $_.Exception.Message
}
if ($docsBefore -ne 0) {
    Stop-Refused 'OPEN_DOCUMENTS' "Illustrator has $docsBefore open document(s); save and close them first"
}

$appVersion = ''
try { $appVersion = [string]$app.Version } catch { $appVersion = 'unknown' }

$record = @{
    status               = 'STARTED'
    note                 = 'STARTED without a later status means the outcome is unknown. Do not assume Illustrator stopped.'
    launcher_pid         = $PID
    jsx                  = $jsxFull
    jsx_sha256           = $actualSha
    illustrator_version  = $appVersion
    documents_before     = $docsBefore
    started_at           = (Get-Date).ToString('o')
    finished_at          = $null
    documents_after      = $null
    error                = $null
    outputs              = @()
}
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

# First write uses CreateNew so an existing record can never be replaced.
$stream = New-Object System.IO.FileStream($resultFull, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write)
try {
    $bytes = $utf8NoBom.GetBytes(($record | ConvertTo-Json -Depth 6))
    $stream.Write($bytes, 0, $bytes.Length)
} finally {
    $stream.Dispose()
}

$exitCode = 0
try {
    # Single attempt. This call blocks until Illustrator finishes or fails.
    [void]$app.DoJavaScriptFile($jsxFull)
    $record.status = 'SCRIPT_RETURNED'
} catch {
    $record.status = 'SCRIPT_ERROR'
    $record.error = $_.Exception.Message
    $exitCode = 3
}

$record.finished_at = (Get-Date).ToString('o')
try { $record.documents_after = [int]$app.Documents.Count } catch { $record.documents_after = -1 }
$record.outputs = @(Get-OutputInfo $dir)
$record.note = 'A returned script and existing files do not prove the .ai file is valid. Open it in Illustrator and check that the paths are editable.'

# Update our own record (created above in this same run).
[System.IO.File]::WriteAllText($resultFull, ($record | ConvertTo-Json -Depth 6), $utf8NoBom)
exit $exitCode
